insert into public.cases (id, title, description, interpretation_a, interpretation_b, evidence_json, image_url, is_backup)
values
('empty-display-case', 'The Empty Display Case', 'At 2 a.m. a museum alarm sounded. Staff reached the gallery within minutes and found the display case of a minor painting open and empty. Nothing else in the gallery had been disturbed.', 'Outsider on impulse: A visitor who stayed hidden after closing got hold of a spare or left-behind key, opened the case on impulse and set off the alarm while slipping out.', 'Staged for insurance: The theft was planned to support a later insurance claim: someone opened the case, removed the painting and deliberately triggered the alarm to leave an official record.', '["The alarm sounded at 2 a.m. and staff reached the gallery within four minutes.","The display case was open and empty; the glass was intact and the lock showed no scratches.","The case''s door sensor logged an opening at 1:58 a.m., two minutes before the alarm.","The night guard''s logbook has a partly smudged entry for 1:45 a.m.","The painting''s insurance valuation was due for renewal that week.","Another gallery had asked to borrow the painting, but no collection date had been agreed."]'::jsonb, null, false),
('silent-call', 'The Silent Call', 'A woman''s landline rang at 3 a.m. When she answered she heard only faint breathing and a ticking sound before the line went dead. Nothing like it had happened to her before.', 'Prank call: A local teenager using a number-spoofing app made the call for fun and played a ticking clock to unsettle her.', 'Equipment fault: A faulty or misconfigured device, such as the new alarm panel or a legacy exchange line, dialled by mistake and produced the noises as line artefacts.', '["The call came at 3:02 a.m. and she answered on the second ring.","She heard faint breathing and a steady ticking; nobody spoke, and the line dropped after about twenty seconds.","A faint cough could be heard just before the line dropped.","The phone records show the calling number belongs to a payphone that was removed last year.","Two neighbours say they received a similar late-night call last month; none since.","Her home alarm company replaced its control panel last week and tested the panel''s dial-out line."]'::jsonb, null, false),
('open-gate', 'The Open Gate', 'A neighbour''s front gate, normally kept locked, has been found open every morning this week. The family is on holiday and arranged a house-sitter whom none of the neighbours has met.', 'House-sitter''s routine: The house-sitter leaves early and forgets to relock the gate behind them, then closes it again later in the day.', 'Someone scouting: A stranger is checking whether the house is watched, opening the gate each morning to see who reacts.', '["The usually locked front gate was found open every morning this week.","The lock is undamaged and nothing visible has been taken from the garden.","The family is away and arranged a house-sitter whom no neighbour has met.","A neighbour saw an unfamiliar person standing near the gate on Tuesday afternoon.","The gate''s latch is old and sticks, and two mornings this week were very windy.","One neighbour says a van parked briefly outside on Monday and Wednesday mornings."]'::jsonb, null, false),
('missing-rows', 'The Missing Rows', 'On Monday morning an accountant found forty rows missing from a shared spreadsheet. A backup from Friday is intact, so nothing is lost for good, but nobody knows how the rows disappeared.', 'Deliberate insider deletion: A colleague with access to the shared login removed the rows on purpose, for example to hide figures, and chose a quiet hour to do it.', 'Compromised login: An outsider obtained the shared credentials, signed in from their own device and deleted the rows, possibly to cause disruption.', '["Forty rows were missing on Monday morning; the file history shows the deletion at 11:52 p.m. on Sunday.","The deletion was made under a shared analyst login that rarely edits this file.","That login signed in on Sunday evening from a device the system had not seen before.","A data-cleaning macro is scheduled for Sunday nights; its log is only written when it finishes without error, and none was written.","The forty deleted rows were one contiguous block.","A colleague says she may have tidied up the sheet on her new laptop over the weekend, but she has not confirmed it."]'::jsonb, null, false),
('parked-van', 'The Parked Van', 'A delivery van sat for forty minutes on a quiet side street two roads away from its scheduled route. The driver was not with it, and the cargo door was shut.', 'Private visit: The driver is visiting someone nearby for private reasons, a regular personal stop unrelated to any delivery, and leaves the van while doing so.', 'Unlogged handover: The driver meets someone at that spot to hand over or collect goods outside the company''s records, then reseals the cargo.', '["The van was parked for forty minutes on a side street two roads from its route, with the driver absent, the cargo door shut and the engine off.","A shop owner says the same van parked in the same spot the day before.","Dispatch received no call from the driver, and the GPS log shows normal pings before and after the stop.","The cargo seal was recorded as intact at the end of the shift.","The depot''s system lists two customers on that street, both with deliveries booked for later in the week.","The van''s maintenance sheet notes a warning light reported last week."]'::jsonb, null, false),
('drawn-curtains', 'The Drawn Curtains', 'All week the curtains of a corner flat have been drawn in the early evening and opened again at dawn. The tenant, who normally keeps them open, has not been seen coming or going.', 'Smart-home timer: The new smart-home hub runs a schedule that moves the curtains, and the tenant is simply away while the system keeps running.', 'Tenant hiding indoors: The tenant is at home but deliberately avoiding contact, staying inside and keeping a strict routine to appear absent.', '["The curtains were drawn at about 6 p.m. and opened at about 6 a.m. every day this week, give or take a few minutes.","The tenant normally keeps the curtains open and has not been seen coming or going all week.","The mail has been collected from the box each day, in the late morning.","A neighbour heard a TV on and off in the evenings but no voices.","The building manager says the tenant installed a smart-home hub last month; nobody knows which devices it controls.","The tenant''s car has not moved from its parking space all week."]'::jsonb, null, true)
